    from math import gcd
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]["content"]
        sol = extract_solution(text)
        if not sol:
            out.append(-1.0)
            continue

        # Check if correct first
        if is_correct(sol, gt):
            # Check if the answer is a simplified fraction
            m = re.search(r'\\dfrac\{([^}]+)\}\{([^}]+)\}|\\frac\{([^}]+)\}\{([^}]+)\}|(\d+)/(\d+)', sol)
            if m:
                if m.group(1) and m.group(2):
                    num_str, den_str = m.group(1).strip(), m.group(2).strip()
                elif m.group(3) and m.group(4):
                    num_str, den_str = m.group(3).strip(), m.group(4).strip()
                else:
                    num_str, den_str = m.group(5).strip(), m.group(6).strip()

                try:
                    num = int(num_str)
                    den = int(den_str)
                    if den == 0:
                        out.append(0.0)
                        continue
                    g = gcd(abs(num), abs(den))
                    if g > 1:
                        out.append(0.0) # Correct but not simplified
                    else:
                        out.append(1.0) # Correct and simplified
                except:
                    out.append(0.5) # Correct but couldn't parse fraction
            else:
                out.append(1.0) # Correct, not a fraction (e.g., integer)
        else:
            out.append(-1.0)
    return out

